import{_ as a,o as n,c as i,a6 as t}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"11 · 系统提示与上下文注入：每轮喂给模型的那坨东西，到底是怎么拼的","description":"上下文远不止消息历史。每轮发给模型的 prompt，是由系统提示、环境信息、项目记忆、动态附件层层拼装出来的。讲清各层该放什么、放哪里，以及一个贯穿始终的分界原则——静态的放高处、动态的放低处，这直接决定了下一篇 Prompt 缓存的成败。","frontmatter":{"title":"11 · 系统提示与上下文注入：每轮喂给模型的那坨东西，到底是怎么拼的","description":"上下文远不止消息历史。每轮发给模型的 prompt，是由系统提示、环境信息、项目记忆、动态附件层层拼装出来的。讲清各层该放什么、放哪里，以及一个贯穿始终的分界原则——静态的放高处、动态的放低处，这直接决定了下一篇 Prompt 缓存的成败。","source":"https://daiw.org/manual/llm-to-agent/context-injection"},"headers":[],"relativePath":"manual/agent/llm-to-agent/context-injection.md","filePath":"manual/agent/llm-to-agent/context-injection.md"}'),l={name:"manual/agent/llm-to-agent/context-injection.md"};function e(p,s,r,h,o,k){return n(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="_11-·-系统提示与上下文注入-每轮喂给模型的那坨东西-到底是怎么拼的" tabindex="-1">11 · 系统提示与上下文注入：每轮喂给模型的那坨东西，到底是怎么拼的 <a class="header-anchor" href="#_11-·-系统提示与上下文注入-每轮喂给模型的那坨东西-到底是怎么拼的" aria-label="Permalink to &quot;11 · 系统提示与上下文注入：每轮喂给模型的那坨东西，到底是怎么拼的&quot;">​</a></h1><blockquote><p>上下文远不止消息历史。每轮发给模型的 prompt，是由系统提示、环境信息、项目记忆、动态附件层层拼装出来的。讲清各层该放什么、放哪里，以及一个贯穿始终的分界原则——静态的放高处、动态的放低处，这直接决定了下一篇 Prompt 缓存的成败。</p></blockquote><p><a href="/Front2Full/manual/agent/llm-to-agent/token-budget">上一篇</a>我们学会了量上下文的大小。但在谈怎么给它“减负”之前，得先看清：<strong>每一轮实际发给模型的那坨东西，到底由哪些部分拼成？</strong> 很多人以为“上下文 = 消息历史”，这只对了一小半。</p><h2 id="一、背景-模型需要-知道自己身处何地" tabindex="-1">一、背景：模型需要“知道自己身处何地” <a class="header-anchor" href="#一、背景-模型需要-知道自己身处何地" aria-label="Permalink to &quot;一、背景：模型需要“知道自己身处何地”&quot;">​</a></h2><p>一个纯粹的消息历史，缺了很多模型干活必需的信息：</p><ul><li>它在<strong>哪个目录</strong>下工作？当前是什么<strong>操作系统</strong>？<strong>今天几号</strong>？</li><li>这个项目有没有<strong>特定约定</strong>(用 pnpm 不用 npm、测试命令是什么、代码风格)？</li><li>用户<strong>这次</strong>提到的那个文件，内容是什么？</li></ul><p>这些都不在“用户说的话”里，但模型必须知道，否则它只能瞎猜(还记得<a href="/Front2Full/manual/agent/llm-to-agent/raw-llm-api">01 篇</a>那个“连今天几号都不知道”的裸模型吗)。所以真实 Agent 每一轮都会把一堆信息<strong>注入</strong>进上下文。搞清楚注入了什么、注入在哪，是上下文工程的必修课。</p><h2 id="二、解决方案-分层拼装一个-prompt" tabindex="-1">二、解决方案：分层拼装一个 prompt <a class="header-anchor" href="#二、解决方案-分层拼装一个-prompt" aria-label="Permalink to &quot;二、解决方案：分层拼装一个 prompt&quot;">​</a></h2><p>每一轮发给模型的完整 prompt，大致由这几层拼成，从“最静态”到“最动态”排列：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─ 系统提示(system)———————————— 最静态、最大、最该被缓存</span></span>
<span class="line"><span>│    · 角色设定、行为准则</span></span>
<span class="line"><span>│    · 工具使用指南、输出规范</span></span>
<span class="line"><span>├─ 环境上下文 ——————————————— 每次会话基本不变</span></span>
<span class="line"><span>│    · cwd、操作系统、日期、shell</span></span>
<span class="line"><span>├─ 项目记忆 / 用户偏好 ———————— 每个项目固定</span></span>
<span class="line"><span>│    · 项目约定(测试命令、风格)、用户长期偏好</span></span>
<span class="line"><span>├─ 消息历史 ————————————————— 随对话增长</span></span>
<span class="line"><span>│    · user / assistant / tool_use / tool_result …</span></span>
<span class="line"><span>└─ 动态附件 ————————————————— 每轮可能变化,最该放在最后</span></span>
<span class="line"><span>     · 本轮引用的文件、检索到的相关记忆、目录结构</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>每一层各司其职：</p><ul><li><strong>系统提示</strong>：定义“你是谁、怎么干活”。它往往很大(几千 token 的行为规范和工具指南)，而且<strong>基本不变</strong>。</li><li><strong>环境上下文</strong>：让模型知道“此时此地”。通常<strong>追加在系统提示之后</strong>，或作为一条会话开头的元信息。</li><li><strong>项目记忆 / 用户偏好</strong>：项目级的约定(那种 <code>AGENTS.md</code> / <code>CLAUDE.md</code> 之类的文件)、用户的长期偏好。通常<strong>前置注入到对话开头</strong>。</li><li><strong>消息历史</strong>：就是<a href="/Front2Full/manual/agent/llm-to-agent/agent-loop">前面</a>一直在滚的那个 <code>messages</code>。</li><li><strong>动态附件</strong>：本轮才需要的、易变的东西——用户刚引用的文件、按相关性临时检索出的记忆片段。</li></ul><h2 id="三、决定性原则-静态放高处-动态放低处" tabindex="-1">三、决定性原则：静态放高处，动态放低处 <a class="header-anchor" href="#三、决定性原则-静态放高处-动态放低处" aria-label="Permalink to &quot;三、决定性原则：静态放高处，动态放低处&quot;">​</a></h2><p>上面那个“从静态到动态”的排列不是随便排的。它遵循一条<strong>贯穿整个上下文工程</strong>的黄金法则：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>把不变的东西放前面，把易变的东西放后面。</strong> 这条原则有两个理由，一个比一个重要：</p><p><strong>① 缓存</strong>(下一篇的主角)：LLM API 的 prompt 缓存是<strong>前缀匹配</strong>的——只有从头开始、一字不差的那段前缀才能命中缓存。所以你把大而稳定的系统提示放最前面，它就能在每一轮里被缓存复用，省下大笔重复计算的钱和延迟。反过来，只要你在靠前的位置塞一个每轮都变的东西(比如把当前时间戳放进系统提示开头)，它后面的一切缓存<strong>全部作废</strong>。</p><p><strong>② 模型注意力</strong>：近期的、靠后的信息，模型通常给予更高的权重。把“本轮最相关的文件”放在最靠近提问的位置，比埋在几千 token 的历史中间，更容易被模型抓住。</p></div><p>这条原则会在下一篇<a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">Prompt 缓存</a>里变成实打实的钱和延迟，这里先把它刻下来。</p><h2 id="四、实现细节-注入的两种姿势与一个陷阱" tabindex="-1">四、实现细节：注入的两种姿势与一个陷阱 <a class="header-anchor" href="#四、实现细节-注入的两种姿势与一个陷阱" aria-label="Permalink to &quot;四、实现细节：注入的两种姿势与一个陷阱&quot;">​</a></h2><h3 id="姿势一-追加到系统提示" tabindex="-1">姿势一：追加到系统提示 <a class="header-anchor" href="#姿势一-追加到系统提示" aria-label="Permalink to &quot;姿势一：追加到系统提示&quot;">​</a></h3><p>环境信息这类“整场会话不变”的东西，适合拼到系统提示末尾：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> buildSystemPrompt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">base</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EnvInfo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;env&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">工作目录: \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">操作系统: \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">今天日期: \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/env&gt;\`</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>注意：环境信息在<strong>一次会话内</strong>通常不变(你不会中途换操作系统)，所以放进系统提示不会破坏缓存。但<strong>日期</strong>是个微妙的例外——如果你精确到秒，它每轮都变，就成了缓存杀手；精确到“天”就安全。<strong>注入动态信息前，先想想它多久变一次。</strong></p><h3 id="姿势二-作为消息注入" tabindex="-1">姿势二：作为消息注入 <a class="header-anchor" href="#姿势二-作为消息注入" aria-label="Permalink to &quot;姿势二：作为消息注入&quot;">​</a></h3><p>用户引用的文件、检索到的记忆，则更适合作为<strong>消息</strong>注入到历史里(通常紧挨着用户的提问)：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> messagesWithContext</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { role: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, content: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`&lt;file path=&quot;src/x.ts&quot;&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fileContent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/file&gt;\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 附件</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">conversationHistory,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="一个贯穿始终的陷阱-别原地改要复用的消息" tabindex="-1">一个贯穿始终的陷阱：别原地改要复用的消息 <a class="header-anchor" href="#一个贯穿始终的陷阱-别原地改要复用的消息" aria-label="Permalink to &quot;一个贯穿始终的陷阱：别原地改要复用的消息&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>注入上下文时，常见的做法是“往消息数组里加东西”。但你要非常小心：凡是会流回下一轮 API 的消息，一旦被你原地修改，就可能悄悄毁掉<a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">Prompt 缓存</a>。</strong> 因为缓存是靠<strong>字节级前缀匹配</strong>的——你把某条历史消息的内容改动一个字节(哪怕只是“顺手规范化一下路径格式”)，从那条消息往后的缓存就全部失效。所以注入时的正确姿势是：<strong>生成新的消息数组用于这次请求，而不去改动那些要长期留在历史里、要复用缓存的原始消息。</strong> 这个“读时拼装、不改原件”的纪律，是缓存能稳定命中的前提——下一篇会把它讲透。</p></div><h2 id="五、小结-上下文是-拼-出来的-不是-堆-出来的" tabindex="-1">五、小结：上下文是“拼”出来的，不是“堆”出来的 <a class="header-anchor" href="#五、小结-上下文是-拼-出来的-不是-堆-出来的" aria-label="Permalink to &quot;五、小结：上下文是“拼”出来的，不是“堆”出来的&quot;">​</a></h2><p>这一篇的核心认知：<strong>发给模型的上下文，是每一轮精心拼装的产物，而不是一个只增不减的消息堆。</strong> 它分层、有序、各有各的注入姿势，而贯穿其中的是一条铁律——<strong>静态放高处、动态放低处</strong>。</p><p>搞清楚了“上下文由什么拼成”，两个方向自然打开：</p><ul><li>往“省”的方向：把靠前的静态部分<strong>缓存</strong>起来，别每轮重算——这是<a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">下一篇 Prompt 缓存</a>。</li><li>往“减”的方向：当靠后的动态部分(主要是历史)膨胀到装不下，把它<strong>压缩</strong>掉——这是<a href="/Front2Full/manual/agent/llm-to-agent/auto-compaction">第 13 篇 自动压缩</a>。</li></ul><p>我们先走“省”这条路。下一篇，Prompt 缓存——整个 Agent 里<strong>省钱省延迟最立竿见影</strong>的一招，以及它那条不容触碰的“字节稳定性”红线。</p><hr><p><strong>本篇对应代码</strong>：配套仓库把静态 <code>SYSTEM_PROMPT</code> 升级为“基础指令 + 环境上下文”的拼装(<code>src/agent.ts</code>)。<code>git checkout article-11</code>。</p>`,33)])])}const d=a(l,[["render",e]]);export{c as __pageData,d as default};
